        \item A complete object $\mathrm{K}^{\bullet}$ in ${\mathcal D} F_{\textup{indcons}}(X)$ is in the heart of the Beilinson $t$-structure if and only if the $\textup{Gr}^{i}\mathrm{K}[i]$ belong to the heart for all $i \in {\mathbb Z}$.
    \end{enumerate}

\label{decalage}
 We define a functor $\textup{Dec} \colon {\mathcal D} F_{\textup{indcons}}(X) \to {\mathcal D} F_{\textup{indcons}}(X)$ which on objects is given by 
\begin{equation}\label{def_Dec}
\textup{Dec}(\mathrm{K}^{\bullet})^{i} = ({}^B\tau_{\leq -i}\mathrm{K}^{\bullet})(-\infty).
\end{equation}

\begin{equation}\label{def_Dec}
\textup{Dec}(\mathrm{K}^{\bullet})^{i} = ({}^B\tau_{\leq -i}\mathrm{K}^{\bullet})(-\infty).
\end{equation}

\label{t_strtucture_DF_cons}
    ${\mathcal D} F_{\textup{cons}}(X)$ is a symmetric monoidal stable $\infty$-category and the Beilinson $t$-structure (from ${\mathcal D} F_{\textup{indcons}}(X)$) restricts to one on ${\mathcal D} F_{\textup{cons}}(X)$. Moreover
    \begin{enumerate}[(a)]
        \item an object $\mathrm{K}^{\bullet}$ in  ${\mathcal D} F_{\textup{cons}}(X)$ is in the heart of the Beilinson $t$-structure iff $\textup{Gr}^{i}[i]\mathrm{K}^{\bullet}$ are perverse.
        \item The functor $\textup{Dec}$ (see Definition \ref{decalage}) preserves the subcategory ${\mathcal D} F_{\textup{cons}}(X)$. 
    \end{enumerate}
